import { BadRequestException, PipeTransform } from "@nestjs/common"
import assert from "node:assert/strict"

class ParseAgePipe implements PipeTransform<string, number> {
    transform(v: string) {
        const n = Number(v)
        if (!Number.isInteger(n) || n < 0 || n > 150) throw new BadRequestException("Yosh noto'g'ri")
        return n
    }
}

const pipe = new ParseAgePipe()
assert.equal(pipe.transform("25"), 25)
console.log("✔ '25' → 25")
for (const bad of ["-1", "200", "abc", "2.5"]) {
    assert.throws(() => pipe.transform(bad), BadRequestException)
    console.log(`✔ '${bad}' → BadRequestException`)
}

import { Injectable } from "@nestjs/common"
import { Test } from "@nestjs/testing"
import assert from "node:assert/strict"

function mockFn<A extends unknown[], R>(impl: (...a: A) => R) {
    const calls: A[] = []
    const fn = (...a: A) => { calls.push(a); return impl(...a) }
    return Object.assign(fn, { calls })
}

abstract class Mailer { abstract send(to: string, subject: string): Promise<void> }

@Injectable()
class InviteService {
    constructor(private readonly mailer: Mailer) {}
    async invite(emails: string[]) { for (const e of emails) await this.mailer.send(e, "Taklifnoma"); return emails.length }
}

async function main() {
    const send = mockFn(async (_to: string, _s: string) => {})
    const m = await Test.createTestingModule({ providers: [InviteService, { provide: Mailer, useValue: { send } }] }).compile()
    assert.equal(await m.get(InviteService).invite(["a@x.uz", "b@x.uz"]), 2)
    assert.deepEqual(send.calls, [["a@x.uz", "Taklifnoma"], ["b@x.uz", "Taklifnoma"]])
    console.log("✔ send 2 marta chaqirildi:", send.calls)
}
main()

