function shippingCost(weightKg: number, city: string) {
    const base = city === "Toshkent" ? 15000 : 30000
    return weightKg <= 1 ? base : base + Math.ceil(weightKg - 1) * 5000
}

const cases = [
    { weightKg: 0.5, city: "Toshkent", expected: 15000 },
    { weightKg: 2.2, city: "Toshkent", expected: 25000 },
    { weightKg: 1, city: "Nukus", expected: 30000 },
    { weightKg: 3, city: "Nukus", expected: 40000 },
]
for (const c of cases) {
    assert.equal(shippingCost(c.weightKg, c.city), c.expected)
    console.log(`✔ ${c.weightKg} kg, ${c.city} → ${c.expected}`)
}

