import { CallHandler, ExecutionContext, Injectable, NestInterceptor } from "@nestjs/common"
import { firstValueFrom, map, of } from "rxjs"
import assert from "node:assert/strict"

@Injectable()
class MaskEmailInterceptor implements NestInterceptor {
    intercept(_ctx: ExecutionContext, next: CallHandler) {
        return next.handle().pipe(map((u: { email: string }) => ({ ...u, email: u.email.replace(/^(.).*(@.*)$/, "$1***$2") })))
    }
}

async function main() {
    const out = await firstValueFrom(new MaskEmailInterceptor().intercept({} as ExecutionContext, { handle: () => of({ id: 1, email: "alivaliyev@mail.uz" }) }))
    assert.deepEqual(out, { id: 1, email: "a***@mail.uz" })
    console.log("✔", out)
}
main()

import { ArgumentsHost, Catch, ExceptionFilter, HttpException, NotFoundException } from "@nestjs/common"
import assert from "node:assert/strict"

@Catch(HttpException)
class JsonErrorFilter implements ExceptionFilter {
    catch(e: HttpException, host: ArgumentsHost) {
        const res = host.switchToHttp().getResponse()
        res.status(e.getStatus()).json({ ok: false, error: e.message })
    }
}

let captured: { status?: number; body?: unknown } = {}
const res = { status(s: number) { captured.status = s; return this }, json(b: unknown) { captured.body = b } }
const host = { switchToHttp: () => ({ getResponse: () => res, getRequest: () => ({}) }) } as unknown as ArgumentsHost

new JsonErrorFilter().catch(new NotFoundException("Yo'q"), host)
assert.deepEqual(captured, { status: 404, body: { ok: false, error: "Yo'q" } })
console.log("✔ filter javobi:", captured)

