import { CallHandler, Controller, ExecutionContext, Get, Injectable, NestInterceptor, UseInterceptors } from "@nestjs/common"
import { Test } from "@nestjs/testing"
import { map } from "rxjs"

@Injectable() class Envelope implements NestInterceptor { intercept(_: ExecutionContext, next: CallHandler) { return next.handle().pipe(map(data => ({ wrapped: true, data }))) } }
@Controller("x") @UseInterceptors(Envelope) class X { @Get() x() { return [1, 2] } }
class PassThrough implements NestInterceptor { intercept(_: ExecutionContext, next: CallHandler) { return next.handle() } }

async function main() {
    for (const override of [false, true]) {
        let b = Test.createTestingModule({ controllers: [X] })
        if (override) b = b.overrideInterceptor(Envelope).useValue(new PassThrough()) as typeof b
        const app = (await b.compile()).createNestApplication({ logger: false })
        await app.listen(0, "127.0.0.1")
        console.log(`override=${override}:`, await (await fetch((await app.getUrl()) + "/x")).text())
        await app.close()
    }
}
main()

