    canActivate(ctx: ExecutionContext) { const roles = this.r.get<string[]>("roles", ctx.getHandler()); return !roles || roles.includes(ctx.switchToHttp().getRequest().user.role) }
}
class C { @SetMetadata("roles", ["admin"]) remove() {} open() {} }
const ctx = (handler: Function, role: string) => ({ getHandler: () => handler, getClass: () => C, switchToHttp: () => ({ getRequest: () => ({ user: { role } }) }) }) as unknown as ExecutionContext

const guard = new RolesGuard(new Reflector())
console.log("admin → remove:", guard.canActivate(ctx(C.prototype.remove, "admin")))
console.log("user → remove:", guard.canActivate(ctx(C.prototype.remove, "user")))
console.log("user → open:", guard.canActivate(ctx(C.prototype.open, "user")))

