function featureEnabled() { return process.env.FEATURE_NEW_CHECKOUT === "1" }

function withEnv(vars: Record<string, string | undefined>, fn: () => void) {
    const old = Object.fromEntries(Object.keys(vars).map(k => [k, process.env[k]]))
    Object.assign(process.env, vars)
    try { fn() } finally { for (const [k, v] of Object.entries(old)) v === undefined ? delete process.env[k] : (process.env[k] = v) }
}
withEnv({ FEATURE_NEW_CHECKOUT: "1" }, () => console.log("test ichida:", featureEnabled()))
