import { Body, CanActivate, Controller, ExecutionContext, Get, Injectable, Module, Post, UnauthorizedException, UseGuards } from "@nestjs/common"
import { JwtModule, JwtService } from "@nestjs/jwt"
import { Test } from "@nestjs/testing"
import assert from "node:assert/strict"

@Injectable()
class JwtGuard implements CanActivate {
    constructor(private readonly jwt: JwtService) {}
    async canActivate(ctx: ExecutionContext) {
        const token = ctx.switchToHttp().getRequest().headers.authorization?.slice(7)
        await this.jwt.verifyAsync(token ?? "").catch(() => { throw new UnauthorizedException() })
        return true
    }
}

@Controller()
class AuthController {
    constructor(private readonly jwt: JwtService) {}
    @Post("login") async login(@Body() b: { password: string }) {
        if (b.password !== "1234") throw new UnauthorizedException()
        return { token: await this.jwt.signAsync({ sub: 1 }) }
    }
    @Get("me") @UseGuards(JwtGuard) me() { return { id: 1 } }
}

@Module({ imports: [JwtModule.register({ secret: "t" })], controllers: [AuthController], providers: [JwtGuard] })
class AppModule {}

async function main() {
    const app = (await Test.createTestingModule({ imports: [AppModule] }).compile()).createNestApplication({ logger: false })
    await app.listen(0, "127.0.0.1")
    const url = await app.getUrl()
    const json = { "Content-Type": "application/json" }

    assert.equal((await fetch(url + "/me")).status, 401)
    console.log("✔ tokensiz /me → 401")
    const wrong = await fetch(url + "/login", { method: "POST", headers: json, body: JSON.stringify({ password: "0000" }) })
    assert.equal(wrong.status, 401)
    console.log("✔ noto'g'ri parol → 401")
    const { token } = await (await fetch(url + "/login", { method: "POST", headers: json, body: JSON.stringify({ password: "1234" }) })).json()
    const me = await fetch(url + "/me", { headers: { authorization: `Bearer ${token}` } })
    assert.equal(me.status, 200)
    console.log("✔ token bilan /me → 200", await me.json())
    await app.close()
}
main()

