import { Body, Controller, Delete, Get, HttpCode, Module, NotFoundException, Param, ParseIntPipe, Patch, Post } from "@nestjs/common"
import { Test } from "@nestjs/testing"
import assert from "node:assert/strict"

@Controller("items")
class ItemsController {
    private items = new Map<number, { id: number; name: string }>()
    private next = 1
    @Post() create(@Body("name") name: string) { const i = { id: this.next++, name }; this.items.set(i.id, i); return i }
    @Get(":id") get(@Param("id", ParseIntPipe) id: number) {
        const i = this.items.get(id)
        if (!i) throw new NotFoundException()
        return i
    }
    @Patch(":id") update(@Param("id", ParseIntPipe) id: number, @Body("name") name: string) {
        const i = this.get(id); i.name = name; return i
    }
    @Delete(":id") @HttpCode(204) remove(@Param("id", ParseIntPipe) id: number) { this.get(id); this.items.delete(id) }
}

@Module({ controllers: [ItemsController] }) class AppModule {}

async function main() {
    const app = (await Test.createTestingModule({ imports: [AppModule] }).compile()).createNestApplication({ logger: false })
    await app.listen(0, "127.0.0.1")
    const url = (await app.getUrl()) + "/items"
    const req = (method: string, path = "", body?: object) =>
        fetch(url + path, { method, headers: { "Content-Type": "application/json" }, body: body && JSON.stringify(body) })

    const created = await (await req("POST", "", { name: "Qalam" })).json()
    assert.deepEqual(created, { id: 1, name: "Qalam" }); console.log("✔ yaratildi", created)
    assert.equal((await req("GET", "/1")).status, 200); console.log("✔ o'qildi")
    assert.equal((await (await req("PATCH", "/1", { name: "Ruchka" })).json()).name, "Ruchka"); console.log("✔ yangilandi")
    assert.equal((await req("DELETE", "/1")).status, 204); console.log("✔ o'chirildi")
    assert.equal((await req("GET", "/1")).status, 404); console.log("✔ endi 404")
    await app.close()
}
main()

