import { Body, CanActivate, Controller, ExecutionContext, Get, Injectable, Module, Post, Req, UnauthorizedException, UseGuards } from "@nestjs/common"
import { Test } from "@nestjs/testing"
import assert from "node:assert/strict"

const users = new Map<string, string>()
const tokens = new Map<string, string>()
const orders: { user: string; item: string }[] = []

@Injectable() class TokenGuard implements CanActivate {
    canActivate(ctx: ExecutionContext) {
        const req = ctx.switchToHttp().getRequest()
        req.user = tokens.get(req.headers.authorization ?? "")
        if (!req.user) throw new UnauthorizedException()
        return true
    }
}

@Controller()
class AppController {
    @Post("register") register(@Body() b: { email: string; password: string }) { users.set(b.email, b.password); return { ok: true } }
    @Post("login") login(@Body() b: { email: string; password: string }) {
        if (users.get(b.email) !== b.password) throw new UnauthorizedException()
        const t = `t-${tokens.size + 1}`; tokens.set(t, b.email); return { token: t }
    }
    @Post("orders") @UseGuards(TokenGuard) order(@Req() req: any, @Body("item") item: string) { orders.push({ user: req.user, item }); return { count: orders.length } }
    @Get("orders") @UseGuards(TokenGuard) mine(@Req() req: any) { return orders.filter(o => o.user === req.user) }
}
@Module({ controllers: [AppController], providers: [TokenGuard] }) class AppModule {}

async function main() {
    const app = (await Test.createTestingModule({ imports: [AppModule] }).compile()).createNestApplication({ logger: false })
    await app.listen(0, "127.0.0.1")
    const url = await app.getUrl()
    const call = async (method: string, path: string, body?: unknown, token?: string) => {
        const res = await fetch(url + path, { method, headers: { "Content-Type": "application/json", ...(token ? { Authorization: token } : {}) }, body: body ? JSON.stringify(body) : undefined })
        return { status: res.status, body: await res.json() }
    }
    const cred = { email: "ali@mail.uz", password: "123" }
    assert.equal((await call("POST", "/register", cred)).status, 201); console.log("✔ ro'yxatdan o'tdi")
    const { body: { token } } = await call("POST", "/login", cred); console.log("✔ login, token:", token)
    assert.equal((await call("POST", "/orders", { item: "choy" })).status, 401); console.log("✔ token'siz buyurtma → 401")
    assert.equal((await call("POST", "/orders", { item: "choy" }, token)).status, 201); console.log("✔ buyurtma berildi")
    assert.deepEqual((await call("GET", "/orders", undefined, token)).body, [{ user: "ali@mail.uz", item: "choy" }]); console.log("✔ o'z buyurtmalari ko'rindi")
    await app.close()
}
main()

