import { Controller, Get, Module } from "@nestjs/common"

@Controller() class C { @Get("a") a() { return "A" } @Get("b") b() { return "B" } }
@Module({ controllers: [C] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const base = await http.app.getUrl()
    const cases: [string, string, number][] = [["/a", "A", 200], ["/b", "B", 200], ["/c", "", 404]]
    let pass = 0
    for (const [path, body, status] of cases) {
        const r = await fetch(base + path)
        const ok = r.status === status && (!body || (await r.text()) === body)
        if (ok) pass++
        console.log(`${ok ? "✔" : "✘"} GET ${path} → ${r.status}`)
    }
    console.log(`\n${pass}/${cases.length} o'tdi`)
    await http.close()
}
main()

