import { CallHandler, Controller, ExecutionContext, Get, Injectable, Module, NestInterceptor } from "@nestjs/common"
import { APP_INTERCEPTOR } from "@nestjs/core"
import assert from "node:assert/strict"
import { map } from "rxjs"

@Injectable() class Envelope implements NestInterceptor { intercept(_: ExecutionContext, n: CallHandler) { return n.handle().pipe(map(data => ({ success: true, data }))) } }
@Controller() class C { @Get("a") a() { return [1] } @Get("b") b() { return { x: 1 } } }
@Module({ controllers: [C], providers: [{ provide: APP_INTERCEPTOR, useClass: Envelope }] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    for (const p of ["/a", "/b"]) assert.equal((await http.get(p)).data.success, true)
    console.log("✔ barcha javoblar { success, data } shaklida")
    await http.close()
}
main()

examples.output:
GET /a → 200 {"success":true,"data":[1]}
GET /b → 200 {"success":true,"data":{"x":1}}
✔ barcha javoblar { success, data } shaklida

