import { Body, Controller, Get, Module, Param, Post, Res } from "@nestjs/common"
import type { Response } from "express"

const items = new Map<string, string>()
@Controller("items") class I {
    @Post() c(@Body("name") name: string, @Res({ passthrough: true }) res: Response) { const id = String(items.size + 1); items.set(id, name); res.location(`/items/${id}`); return { id } }
    @Get(":id") g(@Param("id") id: string) { return { id, name: items.get(id) } }
}
@Module({ controllers: [I] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const created = await http.post("/items", { name: "Choynak" })
    await http.get(created.headers.get("location")!)
    await http.close()
}
main()
